// Items are stored as copies in the save, so a base-stat change in gamedata.js
// (e.g. a homebrew tweak) won't reach gear a hero already owns. Re-sync the
// static base stats by name on load. Battle-rune upgrades (br*), `uses`
// counters, and aspects are left alone — only these immutable base fields sync.
const CANON_STAT_KEYS = ["R", "D", "H", "hnd", "skill", "A"];
function canonItemMap() {
  const map = {};
  [].concat(G.weapons, G.exoticWeapons, G.magicItems, G.armor)
    .forEach((it) => { if (it && it.name) map[it.name] = it; });
  return map;
}
function syncItemBaseStats(hero) {
  if (!hero || !hero.equipped) return;
  const canon = canonItemMap();
  const patch = (it) => {
    if (!it) return;
    const c = canon[it.name];
    if (!c) return;
    CANON_STAT_KEYS.forEach((k) => { if (k in c) it[k] = c[k]; });
  };
  ["weapon", "armor", "shield"].forEach((slot) => patch(hero.equipped[slot]));
  (hero.equipped.accessories || []).forEach(patch);
  (hero.inventory || []).forEach(patch);
}

async function loadHero(id) {
  const blob = await api("GET", `/api/heroes/${id}`);
  state = { id, hero: blob.hero, dungeon: blob.dungeon || null };
  syncItemBaseStats(state.hero);
  view = "play";
  render();
}

