// Manual d6 for a monster's triggered special (e.g. Ragnar's boulder throw).
// Purely a decision aid: it rolls and tells you whether the special fires this
// round. It does NOT apply damage or consume the monster's action — resolve a
// normal 👹 Strike or the special's own button based on the result.
function rollMonsterAbility(mon) {
  const ab = mon.rollAbility;
  if (!ab) return;
  const r = roll(6);
  const [lo, hi] = ab.trigger;
  if (r >= lo && r <= hi) {
    logMsg(`${mon.label}: d6=${r} → ${ab.name}! (fires on ${lo}-${hi}) — use the ${ab.icon || "✨"} ${ab.name} button.`, "miss");
    toast(`${ab.name}! (d6=${r})`, "info");
  } else {
    logMsg(`${mon.label}: d6=${r} → no ${ab.name} (fires on ${lo}-${hi}) — resolve a normal 👹 Strike.`, "hit");
    toast(`No ${ab.name} (d6=${r})`, "info");
  }
}

// Resolve a monster's triggered special attack (e.g. boulder throw, R3 D6). It
// counts as the monster's action for the round and is mitigated by the round's
// shared armor pool, exactly like a normal Strike.
function monsterSpecialAttack(mon) {
  const d = state.dungeon, h = state.hero;
  if (mon.hp <= 0 || !mon.rollAbility) return;
  const ab = mon.rollAbility;
  if (mon.struckRound === d.round &&
      !confirm(`${mon.label} has already acted this round. ${ab.name} anyway?`)) return;
  const ph = ensureMonsterPhase(d);
  const raw = ab.D;
  const absorbed = Math.min(ph.armorLeft, raw);
  const net = raw - absorbed;
  ph.armorLeft -= absorbed;
  h.hp -= net;
  mon.struckRound = d.round;
  logMsg(`${mon.label} — ${ab.name} (R${ab.R} D${ab.D}): ${raw} dmg${absorbed ? ` − ${absorbed} armor` : ""} = ${net} HP lost.`, net > 0 ? "miss" : "hit");
  if (h.hp <= 0) { h.hp = 0; return heroDies(); }
  render(); saveNow();
}

