// Monster instances are spread-copied from the manual at spawn, so a new
// data-driven field (like a rollAbility) won't reach a monster already in a
// live encounter. Re-attach it by name on load — same self-healing idea as
// syncItemBaseStats, scoped to the active room's monsters.
function syncMonsterAbilities(dungeon) {
  if (!dungeon || !dungeon.currentRoom) return;
  const map = {};
  G.monsterManual.forEach((p) => p.monsters.forEach((mn) => { map[mn.name] = mn; }));
  (G.summons || []).forEach((mn) => { map[mn.name] = mn; });
  (dungeon.currentRoom.monsters || []).forEach((mon) => {
    const c = map[mon.name];
    if (c && c.rollAbility) mon.rollAbility = c.rollAbility;
  });
}

async function loadHero(id) {
  const blob = await api("GET", `/api/heroes/${id}`);
  state = { id, hero: blob.hero, dungeon: blob.dungeon || null };
  syncItemBaseStats(state.hero);
  syncMonsterAbilities(state.dungeon);
  view = "play";
  render();
}

