function castUtilitySpell(spellName) {
  const h = state.hero;
  const s = G.spells.find((x) => x.name === spellName);
  const cost = spendSpellAP(s);
  if (cost === null) return;
  // Tangle holds a monster for 3 rounds — track it as a timed active effect with
  // a per-round countdown that auto-expires (movement itself is adjudicated by hand).
  if (s.name === "Tangle") {
    const target = pickAliveMonster("Tangle which monster? (held in place for 3 rounds)");
    if (!target) { h.ap += cost; render(); saveNow(); return; }   // cancelled / no target → refund
    applyBuff(`Tangle: ${target.label}`, {}, 3, `${target.label} can't move`);
    logMsg(`Cast Tangle${cost ? ` [−${cost} AP]` : ""} — ${target.label} held in place for 3 rounds.`, "gold");
    toast(`Tangle · ${target.label} · 3 rounds`, "ok");
    render(); saveNow(); return;
  }
  logMsg(`Cast ${s.name}${cost ? ` [−${cost} AP]` : ""} — ${s.text}`, "gold");
  toast(`${s.name} cast${cost ? ` · −${cost} AP` : ""}`, "ok");
  render(); saveNow();
}

