// Unspent Bonus Rating budget on a never-improved (but eligible) item, else 0.
function pendingBR(it) {
  const budget = it.brBy || 0;
  if (isWeaponItem(it)) return (budget >= 1 && (it.brD || 0) + (it.brH || 0) === 0) ? budget : 0;
  if (it.type === "armor" || it.type === "shield")
    return (budget >= 2 && (it.brA || 0) === 0 && !(it.aspects || []).length) ? budget : 0;
  return 0;
}

