// Unspent Bonus Rating budget still available to allocate on an eligible item,
// else 0. Reflects budget raised by between-dungeon gold purchases, not just the
// find-time budget. Armor/shields need ≥2 unspent (an aspect is the cheapest buy).
function pendingBR(it) {
  const budget = it.brBy || 0;
  if (isWeaponItem(it)) { const u = budget - (it.brD || 0) - (it.brH || 0); return u >= 1 ? u : 0; }
  if (it.type === "armor" || it.type === "shield") {
    const u = budget - (it.brA || 0) * 3 - (it.aspects || []).length * 2;
    return u >= 2 ? u : 0;
  }
  return 0;
}

