// Homebrew store (between dungeons): the full item tables, each priced at its
// sell value. Items are built exactly as a treasure drop would build them so
// their kind/stats — and therefore their price — match the sell economy.
function storeStock() {
  const stock = [];
  G.weapons.forEach((w) => stock.push({ kind: "weapon", ...w }));
  G.exoticWeapons.forEach((w) => stock.push({ kind: "weapon", exotic: true, ...w }));
  G.armor.forEach((a) => stock.push({ kind: a.type, ...a }));
  G.potions.forEach((p) => stock.push({ kind: "potion", name: p.name, text: p.text }));
  G.scrolls.forEach((s) => stock.push({ kind: "scroll", name: s.name, text: s.text }));
  G.magicItems.forEach((mi) => stock.push({ kind: "magic", name: mi.name, text: mi.text, ...mi }));
  return stock;
}

function buyItem(stockItem) {
  const h = state.hero;
  const price = itemSellValue(stockItem);
  if (h.gold < price) { toast(`Need ${price} gold for ${stockItem.name} (have ${h.gold}).`, "err"); return; }
  h.gold -= price;
  // a fresh, independent copy; bought gear carries no Bonus Rating (only found
  // items do) — raise it on the Upgrade tab if desired.
  h.inventory.push(JSON.parse(JSON.stringify(stockItem)));
  logMsg(`Bought ${stockItem.name} for ${price} gold.`, "gold");
  toast(`Bought ${stockItem.name} · −${price}g`, "ok");
  render(); saveNow();
}

function storeList() {
  const h = state.hero;
  const stock = storeStock();
  const groups = [
    ["Weapons", stock.filter((i) => i.kind === "weapon" && !i.exotic)],
    ["Exotic Weapons", stock.filter((i) => i.exotic)],
    ["Armor & Shields", stock.filter((i) => i.kind === "armor" || i.kind === "shield")],
    ["Potions", stock.filter((i) => i.kind === "potion")],
    ["Scrolls", stock.filter((i) => i.kind === "scroll")],
    ["Magic Items", stock.filter((i) => i.kind === "magic")],
  ];
  const box = el("div", {});
  groups.forEach(([label, items]) => {
    if (!items.length) return;
    box.appendChild(el("div", { class: "sub", style: "margin:10px 0 2px" }, label));
    const ul = el("ul", { class: "itemlist" });
    items.forEach((it) => {
      const price = itemSellValue(it);
      ul.appendChild(el("li", {},
        el("span", { class: "grow" }, it.name, el("span", { class: "sub" }, "  ", ...itemStatNodes(it))),
        el("button", {
