          title: h.gold < price ? `Need ${price} gold (have ${h.gold})` : `Buy for ${price} gold`,
          onclick: () => buyItem(it),
        }, `buy · ${price}g`)));
    });
    box.appendChild(ul);
  });
  return box;
}

