function castUtilitySpell(spellName) {
  const h = state.hero;
  const s = G.spells.find((x) => x.name === spellName);
  if (s.name === "Tangle") return castTangle(s);          // its own variable-cost / multi-target flow
  const cost = spendSpellAP(s);
  if (cost === null) return;
  logMsg(`Cast ${s.name}${cost ? ` [−${cost} AP]` : ""} — ${s.text}`, "gold");
  toast(`${s.name} cast${cost ? ` · −${cost} AP` : ""}`, "ok");
  render(); saveNow();
}

// Tangle holds monsters for 3 rounds, tracked as per-monster timed active effects
// with a countdown (movement itself is adjudicated by hand). Homebrew: the base
// cost holds 1 monster; each additional AP spent holds one more.
function castTangle(s) {
  const h = state.hero;
  const BASE = s.ap || 2;
  if (h.ap < BASE) { toast(`Tangle needs at least ${BASE} AP (have ${h.ap}).`, "err"); return; }
  const r = state.dungeon?.currentRoom;
  const alive = r ? r.monsters.filter((m) => m.hp > 0) : [];
  if (!alive.length) { toast("No monster to target with Tangle.", "err"); return; }
  const maxTargets = Math.min(alive.length, 1 + (h.ap - BASE));   // 1 base + 1 per extra AP
  let n = 1;
  if (maxTargets > 1) {
    const input = prompt(`Tangle how many monsters?\n${BASE} AP holds 1; each additional monster costs +1 AP.\nYou can afford up to ${maxTargets} (${alive.length} present, ${h.ap} AP).`, String(maxTargets));
    if (input === null) return;
    n = parseInt(input, 10);
    if (isNaN(n) || n < 1) { toast("Enter a positive number of monsters.", "err"); return; }
    n = Math.min(n, maxTargets);
  }
  // choose n distinct targets (auto-pick when only one candidate remains)
  const remaining = alive.slice(), targets = [];
  for (let i = 0; i < n; i++) {
    if (remaining.length === 1) { targets.push(remaining[0]); break; }
    const list = remaining.map((m, idx) => `${idx + 1}. ${m.label} (${m.hp}/${m.hpMax})`).join("\n");
    const pick = prompt(`Tangle — choose monster ${i + 1} of ${n}:\n${list}\n\nEnter a number (Cancel to stop):`, "1");
    if (pick === null) break;
    const idx = parseInt(pick, 10) - 1;
    if (isNaN(idx) || idx < 0 || idx >= remaining.length) { toast("Invalid choice — stopping.", "err"); break; }
    targets.push(remaining.splice(idx, 1)[0]);
  }
  if (!targets.length) return;                            // nothing chosen → no AP spent
  const cost = BASE + (targets.length - 1);
  h.ap -= cost;
  targets.forEach((t) => applyBuff(`Tangle: ${t.label}`, {}, 3, `${t.label} can't move`));
  const names = targets.map((t) => t.label).join(", ");
  logMsg(`Cast Tangle [−${cost} AP] — ${names} held in place for 3 rounds.`, "gold");
  toast(`Tangle · ${targets.length} monster${targets.length === 1 ? "" : "s"} · −${cost} AP`, "ok");
  render(); saveNow();
}

