// Magic items worn for a passive bonus (by name, so already-looted items work too).
const WORN_EFFECTS = { "Boots of Striding": { movement: 1 } };
// Wearable accessories (no fixed slot): passive-bonus items plus the Amulet of
// Shielding, which only soaks damage while equipped (see amuletAbsorb).
const ACCESSORY_NAMES = new Set([...Object.keys(WORN_EFFECTS), "Amulet of Shielding"]);
const isAccessory = (it) => ACCESSORY_NAMES.has(it.name);
function wornBonus(h, key) {
  return (h.equipped.accessories || []).reduce((s, it) => s + ((WORN_EFFECTS[it.name] || {})[key] || 0), 0);
}
// Equipped Amulet of Shielding soaks unmitigated (post-armor) damage up to its
// remaining charge, then vanishes. Returns {shielded, vanished} for logging.
function amuletAbsorb(net) {
  const h = state.hero;
  if (net <= 0) return { shielded: 0, vanished: false };
  const accs = h.equipped.accessories || [];
  const amulet = accs.find((a) => a.name === "Amulet of Shielding" && (a.uses || 0) > 0);
  if (!amulet) return { shielded: 0, vanished: false };
  const shielded = Math.min(amulet.uses, net);
  amulet.uses -= shielded;
  let vanished = false;
  if (amulet.uses <= 0) { h.equipped.accessories = accs.filter((a) => a !== amulet); vanished = true; }
  return { shielded, vanished };
}

