// Stable signature of an inventory item's full gameplay state. Identical items
// (matching BR allocation, aspects, and remaining uses) share a key and stack
// together; any difference — e.g. an upgraded copy — keeps them on separate lines.
function stackKey(it) {
  const norm = {};
  Object.keys(it).sort().forEach((k) => {
    const v = it[k];
    norm[k] = Array.isArray(v) ? [...v].sort() : v;
  });
  return JSON.stringify(norm);
}

function inventorySection() {
  const h = state.hero;
  if (!h.inventory.length) return el("div", { class: "note" }, "Empty.");
  // group identical items into stacks; the first copy's index is the
  // representative that each action consumes (one copy per click).
  const stacks = [], byKey = {};
  h.inventory.forEach((it, idx) => {
    const key = stackKey(it);
    if (byKey[key] == null) { byKey[key] = stacks.length; stacks.push({ it, idx, count: 1 }); }
    else stacks[byKey[key]].count += 1;
  });
  const ul = el("ul", { class: "itemlist" });
  stacks.forEach(({ it, idx, count }) => {
    const actions = el("span", { class: "btn-row" });
    if (isWeaponItem(it)) actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "weapon") }, "equip"));
    if (it.type === "armor") actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "armor") }, "equip"));
    if (it.type === "shield") actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "shield") }, "equip"));
    // weapon Bonus Rating: split across Damage and/or Hit (needs ≥1 BR)
    if (isWeaponItem(it) && (it.brBy || 0) >= 1)
      actions.appendChild(brButton(it, () => allocateWeaponBR(it)));
    // armor/shield Bonus Rating: choose armor value vs magical aspects (needs ≥2 BR)
    if ((it.type === "armor" || it.type === "shield") && (it.brBy || 0) >= 2)
      actions.appendChild(brButton(it, () => allocateBR(it)));
    if (it.kind === "potion") actions.appendChild(el("button", { class: "btn sm", onclick: () => usePotion(idx) }, "use"));
    // Spell Scroll (1 spell) and Spell book page (2 spells) add spells to your spell book
    if (it.name === "Spell Scroll" || it.name === "Spell book page") {
      const n = it.name === "Spell book page" ? 2 : 1;
      if (baseMemorizeCap(h) > 0) actions.appendChild(el("button", { class: "btn sm", onclick: () => learnSpellModal(idx, n, it.name) }, n === 1 ? "learn spell" : "learn spells"));
      else actions.appendChild(el("span", { class: "sub", title: "only spellcasters keep a spell book" }, "needs a spell book"));
    } else if (it.kind === "scroll") {
