    }
    // worn accessories (Boots of Striding, Amulet of Shielding, …)
    if (isAccessory(it)) actions.appendChild(el("button", { class: "btn sm", onclick: () => equipAccessory(idx) }, "wear"));
    actions.appendChild(el("button", { class: "btn sm danger", title: count > 1 ? "drop one" : "drop", onclick: () => { state.hero.inventory.splice(idx, 1); render(); saveNow(); } }, "drop"));
    const uses = typeof it.uses === "number" ? `  · ${it.uses} use${it.uses === 1 ? "" : "s"} left` : "";
