/* --------------------------------------------------------------- logging -- */
// The full floor's log is kept in state (reset per dungeon); only the most recent
// LOG_RENDER_MAX entries are mounted in the DOM so the list stays cheap to draw.
const LOG_RENDER_MAX = 200;
function logMsg(msg, cls = "") {
  if (!state?.dungeon) return;
  state.dungeon.log = state.dungeon.log || [];
  state.dungeon.log.unshift({ t: msg, c: cls });
  // incremental render: prepend just this entry (O(1)) and trim the DOM tail,
  // instead of rebuilding the whole list on every message.
  const box = $("#log");
  if (box) {
    box.insertBefore(el("div", { class: "entry " + (cls || "") }, msg), box.firstChild);
    while (box.childElementCount > LOG_RENDER_MAX) box.removeChild(box.lastChild);
  }
